@preconcurrency import SwiftNumber
@preconcurrency import Eth
import Foundation

public enum AaveActions {
    public static let creationCode: Hex = ""
    public static let runtimeCode: Hex = ""


    public enum RevertReason : Equatable, Error {
        case unknownRevert(String, String)
    }
    public static func rewrapError(_ error: ABI.Function, value: ABI.Value) -> RevertReason {
        switch (error, value) {
        case let (e, v):
            return .unknownRevert(e.name, String(describing: v))
        }
    }
    public static let errors: [ABI.Function] = []
    public static let functions: [ABI.Function] = [supplyFn, withdrawFn]
    public static let supplyFn = ABI.Function(
            name: "supply",
            inputs: [.address, .address, .uint256, .bool],
            outputs: []
    )

    public static func supply(pool: EthAddress, asset: EthAddress, amount: Number, cappedMax: Bool, withFunctions ffis: EVM.FFIMap = [:]) throws -> Result<(), RevertReason> {
            do {
                let query = try supplyFn.encoded(with: [.address(pool), .address(asset), .uint256(amount), .bool(cappedMax)])
                let result = try EVM.runQuery(bytecode: runtimeCode, query: query, withErrors: errors, withFunctions: ffis)
                let decoded = try supplyFn.decode(output: result)

                switch decoded {
                case  .tuple0:
                    return .success(())
                default:
                    throw ABI.DecodeError.mismatchedType(decoded.schema, supplyFn.outputTuple)
                }
            } catch let EVM.QueryError.error(e, v) {
                return .failure(rewrapError(e, value: v))
            }
    }


    public static func supplyDecode(input: Hex) throws -> (EthAddress, EthAddress, Number, Bool) {
        let decodedInput = try supplyFn.decodeInput(input: input)
        switch decodedInput {
        case let .tuple4(.address(pool), .address(asset), .uint256(amount), .bool(cappedMax)):
            return  (pool, asset, amount, cappedMax)
        default:
            throw ABI.DecodeError.mismatchedType(decodedInput.schema, supplyFn.inputTuple)
        }
    }

    public static let withdrawFn = ABI.Function(
            name: "withdraw",
            inputs: [.address, .address, .uint256],
            outputs: []
    )

    public static func withdraw(pool: EthAddress, asset: EthAddress, amount: Number, withFunctions ffis: EVM.FFIMap = [:]) throws -> Result<(), RevertReason> {
            do {
                let query = try withdrawFn.encoded(with: [.address(pool), .address(asset), .uint256(amount)])
                let result = try EVM.runQuery(bytecode: runtimeCode, query: query, withErrors: errors, withFunctions: ffis)
                let decoded = try withdrawFn.decode(output: result)

                switch decoded {
                case  .tuple0:
                    return .success(())
                default:
                    throw ABI.DecodeError.mismatchedType(decoded.schema, withdrawFn.outputTuple)
                }
            } catch let EVM.QueryError.error(e, v) {
                return .failure(rewrapError(e, value: v))
            }
    }


    public static func withdrawDecode(input: Hex) throws -> (EthAddress, EthAddress, Number) {
        let decodedInput = try withdrawFn.decodeInput(input: input)
        switch decodedInput {
        case let .tuple3(.address(pool), .address(asset), .uint256(amount)):
            return  (pool, asset, amount)
        default:
            throw ABI.DecodeError.mismatchedType(decodedInput.schema, withdrawFn.inputTuple)
        }
    }

}